    flow("#p { overflow: auto; height: 240px } #o { overflow: auto; height: clamp(calc(131px + calc(100% - 132px)), min(197px, calc(81% - 47px)), calc(19% - 179px)) }");
    TEST_ASSERT_EQUAL_STRING("overflow-y:auto;height:clamp(calc(100% - 1px), min(197px, calc(81% - 47px)), calc(19% - 179px))", g_o);
    TEST_ASSERT_EQUAL(240, sh(0));
    TEST_ASSERT_EQUAL(239, sh(1));
    flow("#p { overflow: auto; height: 25ch } #o { overflow: auto; height: clamp(calc(calc(44% + 162px) + 205px), calc(91% - 169px), calc(min(calc(38% - 71px), 19%, calc(46% - 101px)) * 2)) }");
